{"implementation":"def solve(case):
    nodes = list(case["nodes"])
    core = case["core_distance"]
    edges = []
    for index, item in enumerate(case["distances"]):
        u, v, distance = item
        weight = max(distance, core[u], core[v])
        edges.append((weight, u, v, index))
    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2], edge[3]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v, _ in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == max(0, len(nodes) - 1):
                break
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
